function Welcome() {
  return <h1>Welcome back!</h1>;
}

export default function App() {
  return (
    <>
      <Welcome />
      <Welcome />
    </>
  );
}

function PriceTag({ amount, currency = 'EUR', onSale = false }) {
  const label = onSale ? 'Sale' : 'Regular';
  return (
    <p>
      {label}: {amount.toFixed(2)} {currency}
    </p>
  );
}

export default function App() {
  return (
    <>
      <PriceTag amount={12} />
      <PriceTag amount={9.5} currency="USD" onSale />
    </>
  );
}

function RemoveButton({ label, onRemove }) {
  return <button onClick={() => onRemove(label)}>Remove {label}</button>;
}

export default function App() {
  function handleRemove(label) {
    console.log(`remove ${label}`);
  }

  return <RemoveButton label="Draft" onRemove={handleRemove} />;
}

function Card({ title, children }) {
  return (
    <section className="card">
      <h2>{title}</h2>
      {children}
    </section>
  );
}

export default function App() {
  return (
    <Card title="Weather">
      <p>Sunny, 24 °C</p>
      <button>Refresh</button>
    </Card>
  );
}

function Dialog({ children }) {
  return <div role="dialog" className="dialog">{children}</div>;
}

function ConfirmDelete() {
  return (
    <Dialog>
      <h2>Delete file?</h2>
      <p>This cannot be undone.</p>
      <button>Cancel</button>
      <button>Delete</button>
    </Dialog>
  );
}

